"""Module dependency composition.

A campaign's `calls` and `pipes` both point from a dependent to its
prerequisite and together form a DAG.  `compile_order` returns the root plus
all transitive call/pipe prerequisites, prerequisites first, choosing the
lexicographically smallest eligible module whenever several are ready.
`composed_applications` expands an entry's direct pipes through the filters'
own pipes using the composed bindings, so a filter reused with different
bindings is a different application.
"""
import heapq

from .errors import InvalidCampaign


class Pipe(object):
    """A filter application: target, filter and filter->target bindings."""

    __slots__ = ("target", "filter", "bind")

    def __init__(self, target, filter, bind):
        self.target = target
        self.filter = filter
        self.bind = bind


class DependencyGraph(object):
    """Call and pipe prerequisites of every module in a campaign."""

    def __init__(self, modules, calls, pipes):
        self.modules = modules
        self.prerequisites = {name: set() for name in modules}
        self.pipes_by_target = {}
        self._dependents = {name: set() for name in modules}
        for entry in calls or []:
            if not isinstance(entry, list) or len(entry) != 2:
                raise InvalidCampaign("call pair expected")
            caller, callee = entry
            self._reference(caller)
            self._reference(callee)
            self.prerequisites[caller].add(callee)
        for item in pipes or []:
            if not isinstance(item, dict):
                raise InvalidCampaign("pipe must be an object")
            target = self._reference(item.get("target"))
            filter = self._reference(item.get("filter"))
            bind = item.get("bind")
            if not isinstance(bind, dict):
                raise InvalidCampaign("pipe bind must be an object")
            resolved = {}
            for fparam, tparam in bind.items():
                if not isinstance(fparam, str) or not isinstance(tparam, str):
                    raise InvalidCampaign("pipe bind must map names")
                if fparam in resolved:
                    raise InvalidCampaign("filter parameter bound twice")
                resolved[fparam] = tparam
            pipe = Pipe(target, filter, resolved)
            self.pipes_by_target.setdefault(target, []).append(pipe)
            self.prerequisites[target].add(filter)
        for name, deps in self.prerequisites.items():
            for dep in deps:
                self._dependents[dep].add(name)

    def _reference(self, name):
        if not isinstance(name, str) or name not in self.modules:
            raise InvalidCampaign("unknown module reference " + repr(name))
        return name

    def reachable(self, root):
        """The root plus every transitive call/pipe prerequisite."""
        seen = {root}
        stack = [root]
        while stack:
            current = stack.pop()
            for prerequisite in self.prerequisites.get(current, ()):
                if prerequisite not in seen:
                    seen.add(prerequisite)
                    stack.append(prerequisite)
        return seen

    def compile_order(self, root):
        """Prerequisites before dependents, lexicographically when eligible."""
        scope = self.reachable(root)
        pending = {}
        for name in scope:
            pending[name] = sum(1 for dep in self.prerequisites[name] if dep in scope)
        heap = [name for name, count in pending.items() if count == 0]
        heapq.heapify(heap)
        order = []
        while heap:
            name = heapq.heappop(heap)
            order.append(name)
            for dependent in self._dependents[name]:
                if dependent not in scope:
                    continue
                pending[dependent] -= 1
                if pending[dependent] == 0:
                    heapq.heappush(heap, dependent)
        if len(order) != len(scope):
            raise InvalidCampaign("dependency cycle")
        return order

    def composed_applications(self, entry):
        """Every transitive filter application bound to entry parameters."""
        applications = []
        seen = set()
        stack = []
        for pipe in self.pipes_by_target.get(entry, ()):
            mapping = dict(pipe.bind)
            key = (pipe.filter, tuple(sorted(mapping.items())))
            if key in seen:
                continue
            seen.add(key)
            applications.append((pipe.filter, mapping))
            stack.append((pipe.filter, mapping))
        while stack:
            name, mapping = stack.pop()
            for pipe in self.pipes_by_target.get(name, ()):
                composed = {}
                for fparam, tparam in pipe.bind.items():
                    source = mapping.get(tparam)
                    if source is None:
                        raise InvalidCampaign("unbound filter parameter")
                    composed[fparam] = source
                key = (pipe.filter, tuple(sorted(composed.items())))
                if key in seen:
                    continue
                seen.add(key)
                applications.append((pipe.filter, composed))
                stack.append((pipe.filter, composed))
        return applications

    def type_declarations(self, order, modules):
        """Enum, struct and alias names, dependency before user, once each."""
        emitted = []
        visited = set()

        def visit(type):
            name = type.decl
            if name is None or name in visited:
                return
            visited.add(name)
            if isinstance(type, Alias):
                visit(type.type)
                emitted.append(name)
            elif isinstance(type, Struct):
                for field in type.fields.values():
                    visit(field)
                emitted.append(name)
            elif isinstance(type, Enum):
                emitted.append(name)
            elif isinstance(type, Array):
                visit(type.element_type)

        for name in order:
            module = modules[name]
            for _, type in module.params:
                visit(type)
            visit(module.result[1])
        return emitted
